import math

import pytest

from vultr_model_catalog import ModelPricing, ReasoningSupport, normalize_model, parse_catalog, usd_per_million


def models(payload):
    return [normalize_model(document) for document in parse_catalog(payload).documents]


# The pinned output is generated by the TypeScript project (UPDATE_FIXTURES=1 npm test).
@pytest.mark.parametrize("name", ["vultr-catalog", "edge-cases"])
def test_matches_the_pinned_canonical_output(load, name):
    assert [model.to_dict() for model in models(load(f"{name}.json"))] == load(f"{name}.normalized.json")


def test_live_catalog_chat_model_fields_come_out_of_the_nested_modalities(load):
    model = next(m for m in models(load("vultr-catalog.json")) if m.id == "deepseek-v4-flash-0731")
    assert model.context_window == 1_048_576
    assert model.max_output_tokens == 1_048_576
    assert model.input_modalities == ["text", "image"]
    assert model.pricing.prompt == "0.0000001"
    assert model.pricing.completion == "0.00000025"
    assert model.price_per_million() == {
        "prompt": 0.1,
        "cached_prompt": None,
        "cache_write": None,
        "completion": 0.25,
        "internal_reasoning": None,
    }
    assert model.tools and model.streaming
    assert model.reasoning.supports_max_tokens is False
    assert model.reasoning.supported_efforts[0] == "ultra"
    assert model.accepts_input("image") and not model.accepts_input("video")
    assert "temperature" in model.parameters


def test_live_catalog_rerankers_and_image_generators_are_not_chat_models(load):
    everything = models(load("vultr-catalog.json"))
    skipped = [model.id for model in everything if not model.is_chat]
    assert "bge-reranker-v2-m3" in skipped
    assert "z-image-turbo" in skipped
    assert all(model.context_window is not None for model in everything if model.is_chat)


def test_pricing_prefers_the_entry_without_a_utc_window(load):
    model = next(m for m in models(load("edge-cases.json")) if m.id == "windowed-pricing")
    assert model.pricing == ModelPricing(
        prompt="0.000001",
        cached_prompt="0.0000001",
        cache_write="0.00000125",
        completion="0.000003",
        internal_reasoning="0.000004",
        request="0.001",
    )
    assert model.max_prompt_tokens == 30_000
    assert model.structured_outputs is True
    assert model.streaming is False
    assert model.is_ready is False
    assert model.deprecation_date == "2027-01-01"
    assert model.reasoning == ReasoningSupport(
        mandatory=True,
        default_effort="medium",
        default_enabled=True,
        supported_efforts=["high", "medium", "low"],
        supports_max_tokens=True,
    )


def test_a_document_with_nothing_optional_still_normalizes(load):
    model = next(m for m in models(load("edge-cases.json")) if m.id == "bare-minimum")
    assert model.context_window is None
    assert model.max_output_tokens is None
    assert model.pricing == ModelPricing()
    assert model.reasoning is None
    assert model.tools is False
    assert model.is_ready is True
    assert model.is_chat


def test_bad_entries_are_skipped_and_reported_not_fatal(load):
    parsed = parse_catalog(load("edge-cases.json"))
    assert [document["id"] for document in parsed.documents] == ["windowed-pricing", "bare-minimum", "future-schema"]
    assert [(issue.index, issue.id) for issue in parsed.issues] == [
        (2, "future-schema"),
        (3, None),
        (4, "no-modalities"),
        (5, None),
    ]
    assert "parsed anyway" in parsed.issues[0].message


def test_parse_catalog_accepts_a_bare_list_and_rejects_anything_else():
    assert parse_catalog([]).documents == []
    with pytest.raises(TypeError):
        parse_catalog({"models": []})
    with pytest.raises(TypeError):
        parse_catalog(None)


def test_usd_per_million_is_exact():
    assert usd_per_million("0.0000001") == 0.1
    assert usd_per_million("0.00000025") == 0.25
    assert usd_per_million("0.00000005") == 0.05
    assert usd_per_million("0.000003") == 3
    assert usd_per_million("0.00000125") == 1.25
    assert usd_per_million("1") == 1_000_000
    assert usd_per_million("0") == 0
    assert usd_per_million(".5") == 500_000
    assert usd_per_million("2.5e-7") == 0.25
    assert math.isnan(usd_per_million("free"))
